// Pixel traces from the supplied brochure, at its 2048 × 1152 display scale.
// Furniture footprints and wall traces share one coordinate system.
// No fixture is inferred from the position of another fixture.
function plan(bounds,facade,outline,walls,doors,items,rooms,stair=null){
 const [l,t,r,b]=bounds,uv=([x,y])=>[(y-t)/(b-t),facade==='right'?(r-x)/(r-l):(x-l)/(r-l)];
 return {outline:outline.map(uv),walls:walls.map(s=>[...uv(s.slice(0,2)),...uv(s.slice(2))]),doors:doors.map(s=>[...uv(s.slice(0,2)),...uv(s.slice(2))]),items:items.map(([kind,x,y,w,h,yaw,room])=>({kind,center:uv([x,y]),span:[h/(b-t),w/(r-l)],yaw,room})),rooms:Object.fromEntries(Object.entries(rooms).map(([k,[x1,y1,x2,y2]])=>[k,[uv([x1,y1]),uv([x2,y2])]])),stair:stair?[uv(stair.slice(0,2)),uv(stair.slice(2))]:null};
}
